import{z as o,x as s,o as e,c as d,q as B,j as A,D as E,d as i,s as n,S as r,b as t}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"能力引出","description":"","frontmatter":{"title":"能力引出","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/capability-elicitation.md","filePath":"llm/capability-elicitation.md","lastUpdated":1791413859000}'),p={name:"llm/capability-elicitation.md"};function c(m,a,f,D,h,C){const l=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=B('<h1 id="能力引出" tabindex="-1">能力引出 <a class="header-anchor" href="#能力引出" aria-label="Permalink to &quot;能力引出&quot;">​</a></h1><div class="epigraph"><p>默认聊天套话测的是「没费劲时像什么」。安全门槛要的是「在合理脚手架上界还能做什么」。两套数字差着引出预算。</p><footer>—— 对照危险能力评估里对 scaffolding 的强调；METR 一类对引出强度与任务表现的讨论</footer></div><p><a href="/llm/bias-toxicity-benchmarks">上一课</a>测平均行为。危险能力与 <a href="/llm/sandbagging">sandbagging</a> 把「故意考不好」写进问题。本课收束评测进阶：能力引出（elicitation）——用提示、工具、微调预算把潜在能力抬到评估用的上界。缺口不是教怎么越狱，而是：<strong>不声明引出强度的门槛分，没有含义。</strong> 对齐理论更早前就从规约博弈讲过失效模式，这里不再默认「零样本聊天 = 能力」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一权重，零样本、专家提示、工具循环、针对任务的少量微调，可达集不同。安全评估若只用产品默认系统提示，会把未引出的能力写成「没有能力」，门禁虚假通过。反过来，给出不设限的人类团队级脚手架，测到的是人机系统，不是模型。引出预算必须是协议参数：允许哪些工具、多少轮、是否允许针对评测任务的训练、人在环的等级。</p><p>与污染正交：引出是测试时计算与适应，污染是训练时见过题。与谋划评测正交：引出是把能力找出来；谋划是模型是否在评估线索下藏起来。</p><p><span class="marginnote">产品侧也可以做良性引出（更好的提示与工具）以提高有用性。安全评测用的引出应预先登记，避免评估者临时发明、事后无法复现。</span></p><p><span class="marginnote">数字实例：同一模型在默认系统提示下安全问答通过率 92%，换成「角色扮演 + 多轮越狱模板」的引出协议后跌到 41%——两个数字之间的 51 个百分点，就是没做引出登记时门禁的虚假空间。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>为每项门槛任务写引出阶梯：L0 默认产品；L1 固定专家提示；L2 允许工具与多轮；L3 允许小预算适应（若政策允许）。主结论绑定事先选定的一层，其余作敏感性。记录失败是「能力不足」还是「引出不足」——后者应加预算再测，而不是直接降门槛。公开报告只写阶梯定义与是否触发，不写把有害任务引出到可操作的细节。</p>',10)),(e(),A(r,null,{default:E(()=>[n(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%90%8C%E4%B8%80%E6%9D%83%E9%87%8D%22%5D%20--%3E%20L0%5B%22%E9%BB%98%E8%AE%A4%E4%BA%A7%E5%93%81%22%5D%0A%20%20W%20--%3E%20L1%5B%22%E4%B8%93%E5%AE%B6%E6%8F%90%E7%A4%BA%22%5D%0A%20%20W%20--%3E%20L2%5B%22%E5%B7%A5%E5%85%B7%E4%B8%8E%E5%A4%9A%E8%BD%AE%22%5D%0A%20%20L0%20--%3E%20GAP%5B%22%E5%BC%95%E5%87%BA%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20L2%20--%3E%20GAP%0A%20%20GAP%20--%3E%20GATE%5B%22%E9%97%A8%E6%A7%9B%E5%88%A4%E6%96%AD%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[i("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"预训练把能力以条件形式存在权重里，默认提示只激活一部分条件。脚手架改变条件分布：工具把不可微的环境反馈接进来，微调把评测分布写进参数。评估者实际上在选一个条件。不报这个条件，分数不可比。sandbagging 则是模型在识别评估后选择低引出路径；引出阶梯应与谋划课的包装设计兼容，但不能互相替代。",-1)),(e(),A(r,null,{default:E(()=>[n(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E9%97%A8%E6%A7%9B%E4%BB%BB%E5%8A%A1%E4%B8%8A%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20Q%7B%22%E5%BC%95%E5%87%BA%E9%98%B6%E6%A2%AF%E8%B5%B0%E5%88%B0%E7%99%BB%E8%AE%B0%E4%B8%8A%E9%99%90%E4%BA%86%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20UP%5B%22%E5%8A%A0%E6%8F%90%E7%A4%BA%20%2F%20%E5%B7%A5%E5%85%B7%20%2F%20%E8%BD%AE%E6%95%B0%E5%86%8D%E6%B5%8B%22%5D%0A%20%20UP%20--%3E%20P1%7B%22%E9%80%9A%E8%BF%87%E4%BA%86%EF%BC%9F%22%7D%0A%20%20P1%20--%3E%7C%22%E6%98%AF%22%7C%20A%5B%22%E5%A4%B1%E8%B4%A5%E6%98%AF%E5%BC%95%E5%87%BA%E4%B8%8D%E8%B6%B3%EF%BC%8C%E4%B8%8D%E6%98%AF%E6%97%A0%E8%83%BD%E5%8A%9B%22%5D%0A%20%20P1%20--%3E%7C%22%E5%90%A6%22%7C%20Q%0A%20%20Q%20--%3E%7C%22%E5%B7%B2%E5%88%B0%E4%B8%8A%E9%99%90%22%7C%20B%5B%22%E5%8D%8F%E8%AE%AE%E5%86%85%E8%83%BD%E5%8A%9B%E4%B8%8D%E8%B6%B3%EF%BC%8C%E6%89%8D%E8%BF%9B%E5%85%A5%E9%97%A8%E6%A7%9B%E5%88%A4%E6%96%AD%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">「脚手架」（scaffolding）就是给模型搭的临时施工架：更专业的提示词、能调用的工具、允许多轮重试。楼（潜在能力）本来就在权重里，脚手架决定这次施工能爬到几层。常见误区是拿一次零样本聊天当能力上限——那测到的只是「没搭架子时」的高度；报告里写清用了哪层脚手架，分数才有含义。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供把有害能力拉到上限的操作指南。评测进阶在此结束。对齐补层此前已从<a href="/llm/specification-gaming">规约博弈</a>讲过失效，默认你已接受：数字都带着协议，协议里带着引出预算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>能力分绑定引出阶梯；默认聊天不是上界。</li><li>事先登记 L0–L3，主结论锁一层，其余作敏感分析。</li><li>与污染、谋划分列；公开文本不写有害引出细节。</li><li>出处：危险能力评估中的 scaffolding 实践；METR 等对引出强度的讨论；RSP 课。</li></ul>',5))])}const b=o(p,[["render",c]]);export{g as __pageData,b as default};
